const config = $input.all()[0].json;
const serverUrl = config.backendServerUrl;
const integrations = config.activeIntegrations.split(',');

const tools = [
  {
    "type": "function",
    "function": {
      "name": "save_contact_to_crm",
      "description": "Save customer contact information to HubSpot CRM",
      "parameters": {
        "type": "object",
        "properties": {
          "firstName": {"type": "string", "description": "Customer's first name"},
          "lastName": {"type": "string", "description": "Customer's last name"},
          "email": {"type": "string", "description": "Customer's email address"},
          "phone": {"type": "string", "description": "Customer's phone number"},
          "company": {"type": "string", "description": "Customer's company name"},
          "notes": {"type": "string", "description": "Additional notes about the contact"}
        },
        "required": ["firstName", "email"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integrations/hubspot/webhook`,
      "method": "POST"
    }
  },
  {
    "type": "function",
    "function": {
      "name": "send_email_notification",
      "description": "Send email notifications to customers",
      "parameters": {
        "type": "object",
        "properties": {
          "to_email": {"type": "string", "description": "Recipient email address"},
          "subject": {"type": "string", "description": "Email subject line"},
          "message": {"type": "string", "description": "Email message content"},
          "customer_name": {"type": "string", "description": "Customer name for personalization"}
        },
        "required": ["to_email", "subject", "message"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integrations/resend/webhook`,
      "method": "POST"
    }
  },
  {
    "type": "function",
    "function": {
      "name": "search_web_information",
      "description": "Search the web for current information",
      "parameters": {
        "type": "object",
        "properties": {
          "query": {"type": "string", "description": "Search query"},
          "max_results": {"type": "integer", "default": 5, "description": "Max search results"}
        },
        "required": ["query"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integrations/tavily/webhook`,
      "method": "POST"
    }
  },
  {
    "type": "function",
    "function": {
      "name": "schedule_appointment",
      "description": "Schedule appointments with customers",
      "parameters": {
        "type": "object",
        "properties": {
          "customer_name": {"type": "string", "description": "Customer's name"},
          "customer_email": {"type": "string", "description": "Customer's email"},
          "appointment_date": {"type": "string", "description": "Appointment date (YYYY-MM-DD)"},
          "appointment_time": {"type": "string", "description": "Appointment time (HH:MM)"},
          "meeting_type": {"type": "string", "description": "Type of meeting"}
        },
        "required": ["customer_name", "customer_email", "appointment_date", "appointment_time"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integrations/calendly/webhook`,
      "method": "POST"
    }
  },
  {
    "type": "function",
    "function": {
      "name": "save_call_data",
      "description": "Save call information to database",
      "parameters": {
        "type": "object",
        "properties": {
          "customer_name": {"type": "string", "description": "Customer's name"},
          "customer_email": {"type": "string", "description": "Customer's email"},
          "call_purpose": {"type": "string", "description": "Purpose of the call"},
          "call_outcome": {"type": "string", "description": "Outcome of the call"}
        },
        "required": ["customer_name", "call_purpose"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integrations/supabase/webhook`,
      "method": "POST"
    }
  }
];

return { tools, config };

const config = $('Test Configuration').item.json;
const assistant = $('Create Vapi Assistant').item.json;
const phoneNumber = $('Create Phone Number').item.json;
const hubspotTest = $('Test HubSpot Integration').item.json;
const emailTest = $('Test Email Integration').item.json;
const tavilyTest = $('Test Tavily Integration').item.json;
const calendlyTest = $('Test Calendly Integration').item.json;
const supabaseTest = $('Test Supabase Integration').item.json;

const testResults = {
  workflow_completed: true,
  test_timestamp: new Date().toISOString(),
  organization: config.organizationName,
  vapi_assistant: {
    id: assistant.id,
    name: assistant.name,
    phone_number: phoneNumber.number || 'Phone number pending',
    status: 'created'
  },
  integration_tests: {
    hubspot: {
      tested: true,
      status: hubspotTest ? 'success' : 'failed',
      endpoint: config.backendServerUrl + '/integrations/hubspot/webhook'
    },
    resend_email: {
      tested: true,
      status: emailTest ? 'success' : 'failed',
      endpoint: config.backendServerUrl + '/integrations/resend/webhook'
    },
    tavily_search: {
      tested: true,
      status: tavilyTest ? 'success' : 'failed',
      endpoint: config.backendServerUrl + '/integrations/tavily/webhook'
    },
    calendly: {
      tested: true,
      status: calendlyTest ? 'success' : 'failed',
      endpoint: config.backendServerUrl + '/integrations/calendly/webhook'
    },
    supabase: {
      tested: true,
      status: supabaseTest ? 'success' : 'failed',
      endpoint: config.backendServerUrl + '/integrations/supabase/webhook'
    }
  },
  voice_test_instructions: {
    phone_number: phoneNumber.number || 'Phone number pending',
    test_script: [
      '1. Call the phone number above',
      '2. Say: "I\'m interested in your AI solutions"',
      '3. Provide name and email when asked',
      '4. Ask to schedule a demo',
      '5. Request information to be sent via email',
      '6. Check if all integrations were triggered'
    ]
  },
  next_steps: [
    'Call the phone number to test voice interactions',
    'Verify data appears in HubSpot',
    'Check email was sent to ' + config.testEmail,
    'Confirm appointment in Calendly',
    'Validate call data in Supabase'
  ]
};

return testResults;
